// ─── Horario de atención ───────────────────────────────────────────────────────
const BUSINESS_HOURS = {
  // 0 = Domingo, 1 = Lunes, ..., 6 = Sábado
  weekdays: {
    days: [1, 2, 3, 4, 5],
    open: { h: 8, m: 0 },
    close: { h: 17, m: 30 },
  },
  saturday: { days: [6], open: { h: 8, m: 0 }, close: { h: 12, m: 0 } },
};

const OUT_OF_HOURS_MESSAGE = `⏰ *Horario de atención:*

📍 *Manoguayabo, Sto. Dgo. Oeste*
Prolongación Av. 27 de Febrero, Edif. Grupo Avant
Tel. (809) 683-9933 | WS. (849) 867-5788
🕐 Lun–Vie: 8:00–17:30 hs | Sáb: 8:00–12:00 hs

📍 *Urb. Fernández, Sto. Dgo.*
Av. Charles Sumner #8
Tel. (809) 683-6822 | WS. (849) 867-5788
🕐 Lun–Vie: 8:00–18:00 hs | Sáb: 8:00–12:00 hs

📍 *Santiago*
Av. 27 de Febrero
Tel. (809) 683-9933 | WS. (849) 867-5788
🕐 Lun–Vie: 8:00–18:00 hs | Sáb: 8:00–12:00 hs

_Aunque estamos fuera de horario, podés continuar con tu consulta y te responderemos a la brevedad._ 🙌`;

/**
 * Verifica si el momento actual está dentro del horario de atención.
 * Usa zona horaria de República Dominicana (UTC-4, sin DST).
 */
function isWithinBusinessHours() {
  const now = new Date(
    new Date().toLocaleString("en-US", { timeZone: "America/Santo_Domingo" }),
  );
  const day = now.getDay();
  const h = now.getHours();
  const m = now.getMinutes();
  const mins = h * 60 + m; // minutos desde medianoche

  const toMins = ({ h, m }) => h * 60 + m;

  if (BUSINESS_HOURS.weekdays.days.includes(day)) {
    const { open, close } = BUSINESS_HOURS.weekdays;
    return mins >= toMins(open) && mins < toMins(close);
  }

  if (BUSINESS_HOURS.saturday.days.includes(day)) {
    const { open, close } = BUSINESS_HOURS.saturday;
    return mins >= toMins(open) && mins < toMins(close);
  }

  return false; // Domingo u otro día no configurado
}

// ─── Ejecución y Retorno para el Agente de IA ─────────────────────────────────
const abierto = isWithinBusinessHours();

// Las herramientas de n8n para IA requieren que se retorne ESTRICTAMENTE un string
if (abierto) {
  return "SUCCESS: El negocio está abierto actualmente. Procede con la atención normal al cliente.";
} else {
  return OUT_OF_HOURS_MESSAGE;
}

